import React from 'react';
import { Text } from '@fiverr-private/typography';
import { type Types } from '@fiverr-private/theme';
import type { ComponentWithChildren } from '../types';
import { ALERT_TEXT_ID } from '../constants';

const AlertText = ({
  children,
  dataTrackTag = 'alert_text',
  dataTrackValue,
}: ComponentWithChildren & Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'>) => (
  <Text dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} color="inherit" size="b_sm">
    {children}
  </Text>
);

AlertText.id = ALERT_TEXT_ID;
AlertText.displayName = 'AlertText';

export default AlertText;
