import React from 'react';
import { Container } from '@fiverr-private/layout_components';
import { type Types } from '@fiverr-private/theme';
import type { ComponentWithChildren } from '../types';
import { ALERT_ICON_ID } from '../constants';
import { useAlertContext } from '../AlertContext';

const AlertIcon = ({
  children,
  dataTrackTag = 'alert_icon',
  dataTrackValue,
}: ComponentWithChildren & Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'>) => {
  const { shouldCenterIcon } = useAlertContext();

  return (
    <Container
      as="span"
      display="flex"
      flexShrink={0}
      paddingTop={shouldCenterIcon ? undefined : '0.5'}
      marginTop={shouldCenterIcon ? undefined : 'px'}
      marginRight="2"
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
    >
      {children}
    </Container>
  );
};

AlertIcon.id = ALERT_ICON_ID;
AlertIcon.displayName = 'AlertIcon';

export default AlertIcon;
