import React from 'react';
import { Box } from '@fiverr-private/theme';
import type { ComponentWithChildren } from '../types';
import { ALERT_ACTIONS_ID } from '../constants';
import { useAlertContext } from '../AlertContext';

const AlertActions = ({ children }: ComponentWithChildren) => {
  const { forceMobileDesign } = useAlertContext();

  return (
    <Box
      display="flex"
      marginTop={forceMobileDesign ? '4' : { default: '4', md: '0' }}
      marginLeft={forceMobileDesign ? '0' : { default: '0', md: '8' }}
      alignSelf={forceMobileDesign ? 'flexEnd' : { default: 'flexEnd', md: 'center' }}
      alignItems="center"
      whiteSpace="nowrap"
      flexShrink={0}
      gap="4"
    >
      {children}
    </Box>
  );
};

AlertActions.id = ALERT_ACTIONS_ID;
AlertActions.displayName = 'AlertActions';

export default AlertActions;
