import React from 'react';
import { Button, TextButton } from '@fiverr-private/button';
import type { AlertActionButtonProps } from '../types';

const AlertActionButton = ({
  children,
  intent = 'primary',
  onClick,
  href,
  dataTrackTag = 'alert_action_button',
  dataTrackValue,
}: AlertActionButtonProps) => {
  const ButtonComponent = intent === 'primary' ? Button : TextButton;

  return (
    <ButtonComponent
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
      onClick={onClick}
      href={href}
      target={href ? '_blank' : undefined}
      size="sm"
    >
      {children}
    </ButtonComponent>
  );
};

export default AlertActionButton;
