import React from 'react';
import { I18n } from '@fiverr-private/i18n-react';
import { useAlertContext } from '../AlertContext';
import type { AlertDismissButtonProps } from '../types';
import AlertActionButton from '../AlertActionButton';

const AlertDismissButton = ({
  onClick,
  dataTrackTag = 'alert_dismiss_button',
  dataTrackValue,
}: AlertDismissButtonProps) => {
  const { setDismissed } = useAlertContext();

  return (
    <AlertActionButton
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
      onClick={(e) => {
        setDismissed(true);
        onClick?.(e);
      }}
      intent="secondary"
    >
      <I18n k="feedback.alert.dismiss" />
    </AlertActionButton>
  );
};

AlertDismissButton.displayName = 'AlertDismissButton';

export default AlertDismissButton;
