import React from 'react';
import { Text } from '@fiverr-private/typography';
import { type Types } from '@fiverr-private/theme';
import type { ComponentWithChildren } from '../types';
import { ALERT_TITLE_ID } from '../constants';

const AlertTitle = ({
  children,
  dataTrackTag = 'alert_title',
  dataTrackValue,
}: ComponentWithChildren & Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'>) => (
  <Text dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} fontWeight="semibold" color="inherit" size="b_sm">
    {children}
  </Text>
);

AlertTitle.id = ALERT_TITLE_ID;
AlertTitle.displayName = 'AlertTitle';

export default AlertTitle;
