import React, { useState } from 'react';
import { findChildByType } from '@fiverr-private/ui_utils';
import { Container } from '@fiverr-private/layout_components';
import type { AlertProps } from './types';
import { ALERT_ACTIONS_ID, ALERT_ICON_ID, ALERT_TEXT_ID, ALERT_TITLE_ID, VARIANTS_CONFIG } from './constants';
import { AlertContext } from './AlertContext';
import AlertIcon from './AlertIcon';

const Alert = ({
  variant,
  showIcon = true,
  children,
  forceMobileDesign = false,
  dataTrackTag = 'alert',
  ...restProps
}: AlertProps) => {
  const [dismissed, setDismissed] = useState(false);
  const alertTitle = findChildByType(children, ALERT_TITLE_ID);
  const alertText = findChildByType(children, ALERT_TEXT_ID);
  const alertActions = findChildByType(children, ALERT_ACTIONS_ID);
  const alertIcon = findChildByType(children, ALERT_ICON_ID);

  const shouldCenterIcon = !alertTitle && Boolean(alertActions);

  const { Icon, backgroundColor, borderColor } = VARIANTS_CONFIG[variant];

  if (dismissed) {
    return null;
  }

  return (
    <AlertContext.Provider value={{ variant, setDismissed, forceMobileDesign, shouldCenterIcon }}>
      <Container
        display="flex"
        alignItems={shouldCenterIcon && !forceMobileDesign ? { md: 'center' } : undefined}
        padding="4"
        borderRadius="lg"
        color="grey_1200"
        backgroundColor={backgroundColor}
        borderColor={borderColor}
        borderWidth="sm"
        role="alert"
        {...restProps}
        dataTrackTag={dataTrackTag}
      >
        {showIcon &&
          (alertIcon || (
            <AlertIcon>
              <Icon size="sm" />
            </AlertIcon>
          ))}
        <Container
          display="flex"
          flex={1}
          direction={forceMobileDesign ? 'column' : { default: 'column', md: 'row' }}
          justifyContent={forceMobileDesign ? undefined : { md: 'spaceBetween' }}
          color="inherit"
          alignItems={shouldCenterIcon && !forceMobileDesign ? { md: 'center' } : undefined}
        >
          <Container>
            {alertTitle}
            {alertText}
          </Container>
          {alertActions}
        </Container>
      </Container>
    </AlertContext.Provider>
  );
};

Alert.displayName = 'Alert';

export default Alert;
